(() => {
'use strict';
const cafes=window.MATCHA_CAFES||[];
const $=(s,p=document)=>p.querySelector(s), $$=(s,p=document)=>[...p.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fold=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().replace(/[’']/g,'').trim();
const iconPaths={
 bookmark:'<path d="M6 4h12v17l-6-4-6 4z"/>',bookmark_added:'<path d="M6 4h12v17l-6-4-6 4z"/><path d="m9 10 2 2 4-4"/>',bookmark_remove:'<path d="M6 4h12v17l-6-4-6 4z"/><path d="M9 10h6"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',search_off:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5M3 3l18 18"/>',
 arrow_outward:'<path d="M6 18 18 6M6 6h12v12"/>',south_east:'<path d="m6 6 12 12M6 18h12V6"/>',location_on:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',
 menu_book:'<path d="M12 6v15M3 4c3-1 6 0 9 2 3-2 6-3 9-2v14c-3-1-6 0-9 2-3-2-6-3-9-2z"/>',apps:'<rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><rect x="14" y="14" width="6" height="6" rx="1"/>',
 local_cafe:'<path d="M4 8h13v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4zM17 9h2a3 3 0 1 1 0 6h-2M7 3v2M11 2v3M15 3v2M3 22h17"/>',emoji_food_beverage:'<path d="M4 8h13v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4zM17 9h2a3 3 0 1 1 0 6h-2M9 2v3M13 2v3"/>',
 nutrition:'<path d="M12 7c-5-5-13 3-7 10 2 3 4 4 7 3 3 1 5 0 7-3 6-7-2-15-7-10Z"/><path d="M12 7c-1-4 1-6 4-6 0 3-1 5-4 6Z"/>',spa:'<path d="M12 3c-5 5-5 9 0 13 5-4 5-8 0-13Z"/><path d="M12 16C8 10 4 10 2 10c0 7 5 11 10 11s10-4 10-11c-2 0-6 0-10 6Z"/>',
 eco:'<path d="M20 3C8 2 3 7 5 14c1 5 9 8 13 1 2-4 2-8 2-12Z"/><path d="m4 21 11-11"/>',cake:'<path d="M4 12h16v9H4zM4 15c2 3 4-3 6 0s4-3 6 0 4 0 4 0M7 8h10v4H7zM12 3v5M12 1v1"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',edit_note:'<path d="M4 5h10M4 10h7M4 15h5M13 20l2-5 5-5 3 3-5 5z"/>',ios_share:'<path d="M5 11v10h14V11M12 16V2m-4 4 4-4 4 4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'
};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[n]||iconPaths.eco}</svg>`;
const money=v=>typeof v==='number'?'A$'+v.toFixed(2):v||'Hỏi giá tại quán';
const safeURL=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}};
const external=(url,label,cls='')=>`<a class="${cls}" href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${label}</a>`;
const photo=(c,cls='')=>`<div class="photo photo-${c.photo} ${cls}" role="img" aria-label="Ảnh minh hoạ món matcha; không phải ảnh của ${esc(c.name)}"></div>`;
const cafeURL=c=>'./cafe-spotlight.html?cafe='+encodeURIComponent(c.id);
const categories=[['all','Tất cả','apps'],['latte','Matcha latte','local_cafe'],['fruit','Matcha trái cây','nutrition'],['pure','Matcha thuần','spa'],['dessert','Bánh & tráng miệng','cake'],['hojicha','Hojicha','emoji_food_beverage']];
const catName=id=>categories.find(c=>c[0]===id)?.[1]||id;
const read=(key,fallback=[])=>{try{const v=JSON.parse(localStorage.getItem(key));return Array.isArray(v)?v:fallback;}catch{return fallback;}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('Trình duyệt chưa lưu được dữ liệu. Thử kiểm tra dung lượng hoặc cài đặt riêng tư.');return false;}};
let saved=read('matcha.saved.v1').filter(id=>cafes.some(c=>c.id===id));
let notes=read('matcha.notes.v1');
let suggestions=read('matcha.suggestions.v1');
let toastTimer, directoryApply, dialogFocus;
const content=$('#page-content'), dialog=$('#site-dialog');
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
function toast(t){const el=$('#toast');el.textContent=t;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4200);}
function openDialog(markup){dialogFocus=document.activeElement;$('#dialog-content').innerHTML=markup;if(!dialog.open)dialog.showModal();}
function closeDialog(){dialog.close();}
$('.dialog-close').addEventListener('click',closeDialog);
dialog.addEventListener('close',()=>dialogFocus?.isConnected&&dialogFocus.focus());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
function syncSaved(){
 $$('.saved-count').forEach(e=>e.textContent=saved.length);
 $$('[data-save]').forEach(b=>{const c=cafes.find(c=>c.id===b.dataset.save);const yes=saved.includes(b.dataset.save);b.setAttribute('aria-pressed',String(yes));b.setAttribute('aria-label',(yes?'Bỏ lưu ':'Lưu ')+(c?.name||'quán'));const i=$('.icon',b);if(i)i.outerHTML=icon(yes?'bookmark_added':'bookmark');const label=$('[data-save-label]',b);if(label)label.textContent=yes?'Đã lưu quán':'Lưu quán';});
}
function toggleSave(id){if(!cafes.some(c=>c.id===id))return;const next=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];if(write('matcha.saved.v1',next)){saved=next;syncSaved();directoryApply?.();if(dialog.open&&dialog.dataset.mode==='saved')renderSaved();toast(saved.includes(id)?'Đã thêm quán vào danh sách của bạn.':'Đã bỏ lưu quán.');}}
function renderSaved(){const root=$('#saved-results');if(!root)return;root.innerHTML=saved.length?saved.map(id=>{const c=cafes.find(c=>c.id===id);return `<div class="saved-result"><a href="${cafeURL(c)}">${photo(c)}<span><strong>${esc(c.name)}</strong><small>${esc(c.suburb)} · ${c.reference===null?'Chưa có giá xác minh':money(c.reference)}</small></span></a><button type="button" data-save="${c.id}" aria-label="Bỏ lưu ${esc(c.name)}">${icon('bookmark_remove')}</button></div>`;}).join(''):'<p class="dialog-intro">Bạn chưa lưu quán nào. Chạm biểu tượng bookmark trên một quán để bắt đầu.</p><a class="primary" href="./index.html#directory">Khám phá các quán '+icon('arrow_outward')+'</a>';}
function openSaved(){dialog.dataset.mode='saved';openDialog('<p class="eyebrow">Dành cho một ngày matcha</p><h2 id="dialog-title">Những quán bạn đã lưu.</h2><p class="dialog-intro">Danh sách lưu trên trình duyệt này, không đồng bộ giữa các thiết bị.</p><div id="saved-results"></div>');renderSaved();}
function about(){dialog.dataset.mode='about';openDialog(`<p class="eyebrow">Một cuốn sổ có nguồn</p><h2 id="dialog-title">Thông tin được chọn thế nào?</h2><div class="dialog-intro"><p>Danh sách đầu tiên gồm 10 địa điểm, tương ứng 8 thương hiệu. Địa chỉ và món được đối chiếu qua website quán hoặc City of Melbourne ngày 26.10.2026.</p><p>Giá chính thức là giá có trên website/menu của quán. Little Rogue dùng giá từ một trang tổng hợp và được đánh dấu riêng. itteki South Yarra dùng menu theo mùa. Một số quán chưa có giá online xác minh được.</p><p>Bộ lọc giá và sắp xếp theo giá dùng món đồ uống tham khảo được ghi tên trên từng thẻ; không dùng giá bánh hay phụ thu. Các món tham khảo có thể khác nhau giữa quán. Mức giá chưa gồm mọi lựa chọn sữa, size, topping và phụ thu.</p><p>Menu hiển thị là tuyển chọn món, không phải toàn bộ thực đơn. Mở liên kết nguồn trong từng hồ sơ để xem menu gốc. Giờ mở cửa có thể thay đổi vào ngày lễ.</p><p>Ảnh được tạo để minh hoạ không khí và món matcha, không mô tả món thực tế hay không gian của bất kỳ quán nào. Không có điểm đánh giá hoặc số lượt review tự tạo.</p><p>Quán đã lưu, ghi chú và gợi ý quán chỉ nằm trên trình duyệt này. Biểu mẫu sổ tay không gửi nội dung đến quán hoặc một ban biên tập.</p></div>`);}
function priceSource(c){return c.priceType==='secondary'?'Giá từ nguồn tổng hợp':c.priceType==='seasonal'?'Menu theo mùa · cần xác nhận':c.reference===null?'Nguồn món & địa chỉ':'Giá từ website quán';}
function card(c){return `<article class="cafe-card"><div class="card-image-wrap"><a class="card-image-link" href="${cafeURL(c)}" aria-label="Xem menu ${esc(c.name)}">${photo(c)}</a><span class="card-area">${esc(c.suburb)}</span><button type="button" class="save" data-save="${c.id}" aria-label="Lưu ${esc(c.name)}" aria-pressed="${saved.includes(c.id)}">${icon(saved.includes(c.id)?'bookmark_added':'bookmark')}</button><span class="card-photo-caption">Ảnh minh hoạ</span></div><div class="card-body"><div class="card-meta">${icon('eco')} ${esc(catName(c.categories.includes('pure')?'pure':c.categories.includes('dessert')?'dessert':'latte'))}</div><h3><a href="${cafeURL(c)}">${esc(c.name)}</a></h3><p class="card-description">${esc(c.description)}</p>${external(c.directions,icon('location_on')+`<span>${esc(c.address)}</span>`,'address')}<div class="price-box"><small>${esc(c.referenceLabel)}</small><strong class="${c.reference===null?'unknown-price':''}">${c.reference===null?'Hỏi giá tại quán':money(c.reference)}</strong></div><ul class="mini-menu">${c.menu.slice(0,2).map(([n,v])=>`<li><span>${esc(n)}</span><span>${esc(money(v))}</span></li>`).join('')}</ul><div class="source-mini">${external(c.menuUrl,esc(priceSource(c))+' ↗')}<br>Đối chiếu nguồn: 26.10.2026</div></div><a class="card-bottom" href="${cafeURL(c)}"><span>Menu & thông tin quán</span>${icon('arrow_outward')}</a></article>`;}
function renderDirectory(){
 content.innerHTML=`<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="pill"><span class="pill-dot"></span> MELBOURNE MATCHA GUIDE</span></p><h1>Một chút xanh,<br><em>một góc Melbourne.</em></h1><p>Từ một ly matcha trên con hẻm quen đến một tách trà Nhật thật chậm. Tìm quán hợp gu, xem menu và chọn điểm hẹn tiếp theo.</p><a class="primary" href="#directory">Tìm tách matcha của bạn ${icon('south_east')}</a><div class="hero-stats"><div><b>10</b><span>địa điểm để khám phá</span></div><div><b>5</b><span>khu vực Melbourne</span></div><div><b>AUD</b><span>giá có nguồn tham khảo</span></div></div></div><div class="hero-image"><div class="photo photo-0" role="img" aria-label="Ảnh minh hoạ một ly iced matcha latte trên bàn đá, cùng chổi chasen"></div><div class="hero-stamp" aria-hidden="true"><small>TAKE A</small><b>抹茶</b><small>LITTLE PAUSE</small></div><span class="photo-caption">Ảnh minh hoạ · matcha mood</span><div class="hero-note">Your next little ritual.<small>NAARM / MELBOURNE</small></div></div></section><div class="intro-strip"><span>${icon('location_on')} Melbourne, một tách trà mỗi lần.</span><span>${icon('menu_book')} Menu & giá có nguồn đối chiếu</span><span>${icon('bookmark')} Lưu một góc nhỏ cho riêng bạn</span></div><section class="directory" id="directory"><div class="section-heading"><div><p class="eyebrow">THE MATCHA DIRECTORY</p><h2>Hôm nay, bạn muốn uống gì?</h2></div><a class="text-link" href="./matcha-map-and-suburbs.html">Khám phá khu vực ${icon('arrow_outward')}</a></div><div class="filters"><div class="search-wrap">${icon('search')}<input type="search" id="cafe-search" placeholder="Tên quán, khu vực hoặc món bạn thích…" aria-label="Tìm theo tên quán, khu vực hoặc món" autocomplete="off"><button type="button" id="clear-search" class="clear-search" aria-label="Xoá từ khoá" hidden>×</button><kbd>⌘ K</kbd></div><div class="category-row" role="group" aria-label="Loại món">${categories.map(([id,label,ic])=>`<button type="button" class="chip" data-category="${id}" aria-pressed="${id==='all'}">${icon(ic)} ${label}<small>${id==='all'?cafes.length:cafes.filter(c=>c.categories.includes(id)).length}</small></button>`).join('')}</div><div class="filter-selects"><label>KHU VỰC<select id="suburb-filter"><option value="all">Tất cả khu vực</option>${[...new Set(cafes.map(c=>c.suburb))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>GIÁ MÓN THAM KHẢO<select id="price-filter"><option value="all">Tất cả mức giá</option><option value="under8">Dưới A$8</option><option value="8to10">A$8 – A$10</option><option value="over10">Trên A$10</option><option value="unknown">Chưa có giá xác minh</option></select></label><label>SẮP XẾP<select id="sort-filter"><option value="curated">Thứ tự giới thiệu</option><option value="price-asc">Giá: thấp đến cao</option><option value="price-desc">Giá: cao đến thấp</option><option value="name">Tên quán: A–Z</option></select></label><label class="saved-filter"><input type="checkbox" id="saved-filter">Chỉ quán đã lưu</label><button type="button" class="reset" id="reset-filters">Xoá bộ lọc</button></div></div><div class="results-bar"><strong id="results-count" aria-live="polite"></strong><span>Đồ uống tham khảo · Giá AUD · Ảnh minh hoạ</span></div><div class="results-grid" id="directory-grid"></div></section><section class="guide"><div class="section-heading"><div><p class="eyebrow">FIND YOUR MATCHA MOMENT</p><h2>Matcha theo cách của bạn.</h2></div></div><div class="guide-grid"><article class="guide-card"><span class="number">01 / MỘT LY THẬT QUEN</span><h3>Bắt đầu với latte.</h3><p>Matcha cùng sữa là một cách dễ làm quen. Xem món nóng hoặc đá trong menu và hỏi quán về độ ngọt bạn thích.</p><button class="text-link" data-quick-category="latte" type="button">Tìm matcha latte ${icon('arrow_outward')}</button></article><article class="guide-card"><span class="number">02 / MỘT KHOẢNG THẬT CHẬM</span><h3>Thưởng một tách trà.</h3><p>Muốn thử matcha không sữa? Tìm usucha hoặc ceremonial matcha. Hỏi nhân viên về loại trà đang phục vụ hôm nay.</p><button class="text-link" data-quick-category="pure" type="button">Khám phá matcha thuần ${icon('arrow_outward')}</button></article><article class="guide-card"><span class="number">03 / THÊM MỘT CHÚT NGỌT</span><h3>Để dành chỗ cho bánh.</h3><p>Một chiếc cookie, tart hoặc gelato. Duyệt những quán có món ngọt và xem giá món cụ thể trước khi ghé.</p><button class="text-link" data-quick-category="dessert" type="button">Xem bánh & tráng miệng ${icon('arrow_outward')}</button></article></div></section><div class="sources-note">${icon('info')}<p>Menu là tuyển chọn món, giá là mức tham khảo từ nguồn online được đối chiếu ngày 26.10.2026. Size, sữa, topping, chi nhánh và ngày lễ có thể làm thay đổi giá. Quán chưa có giá xác minh sẽ được ghi rõ. <button class="text-link" type="button" data-about>Xem cách tổng hợp thông tin</button></p></div>`;
 const query=new URLSearchParams(location.search);
 const requestedSuburb=query.get('suburb')==='CBD'?'Melbourne CBD':query.get('suburb');
 const state={q:query.get('q')||'',category:categories.some(c=>c[0]===query.get('category'))?query.get('category'):'all',suburb:cafes.some(c=>c.suburb===requestedSuburb)?requestedSuburb:'all',price:['under8','8to10','over10','unknown'].includes(query.get('price'))?query.get('price'):'all',sort:['price-asc','price-desc','name'].includes(query.get('sort'))?query.get('sort'):'curated',saved:query.get('saved')==='1'};
 const q=$('#cafe-search'),sub=$('#suburb-filter'),pr=$('#price-filter'),sort=$('#sort-filter'),sv=$('#saved-filter');
 q.value=state.q;sub.value=state.suburb;pr.value=state.price;sort.value=state.sort;sv.checked=state.saved;
 function apply(){
  const tokens=fold(state.q).split(/\s+/).filter(Boolean);
  let found=cafes.filter(c=>{const text=fold([c.name,c.suburb,c.address,c.description,c.keywords,...c.categories.map(catName),...c.menu.map(x=>x[0])].join(' '));const price=c.reference;return tokens.every(t=>text.includes(t))&&(state.category==='all'||c.categories.includes(state.category))&&(state.suburb==='all'||c.suburb===state.suburb)&&(!state.saved||saved.includes(c.id))&&(state.price==='all'||state.price==='unknown'&&price===null||price!==null&&(state.price==='under8'&&price<8||state.price==='8to10'&&price>=8&&price<=10||state.price==='over10'&&price>10));});
  if(state.sort==='name')found.sort((a,b)=>a.name.localeCompare(b.name,'vi'));
  if(state.sort.startsWith('price-'))found.sort((a,b)=>a.reference===null?(b.reference===null?0:1):b.reference===null?-1:(state.sort==='price-asc'?a.reference-b.reference:b.reference-a.reference));
  $('#results-count').textContent=`${found.length} / ${cafes.length} địa điểm`;
  $('#directory-grid').innerHTML=found.length?found.map(card).join(''):`<div class="empty">${icon('search_off')}<h3>Chưa tìm thấy tách trà ấy.</h3><p>Thử tên quán, “Carlton”, “dâu” hoặc bớt một bộ lọc.<br>${state.saved?'Bạn có thể lưu quán bằng biểu tượng bookmark trên thẻ.':''}</p><button class="primary" type="button" data-reset>Khám phá lại tất cả ${icon('arrow_outward')}</button></div>`;
  $$('.chip[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===state.category)));
  $('#clear-search').hidden=!state.q;syncSaved();
  const params=new URLSearchParams();for(const key of ['q','category','suburb','price','sort'])if(state[key]&&state[key]!==({category:'all',suburb:'all',price:'all',sort:'curated'}[key]||''))params.set(key,state[key]);if(state.saved)params.set('saved','1');
  const search=params.toString();history.replaceState(null,'',location.pathname+(search?'?'+search:'')+location.hash);
 }
 directoryApply=apply;
 const reset=()=>{Object.assign(state,{q:'',category:'all',suburb:'all',price:'all',sort:'curated',saved:false});q.value='';sub.value='all';pr.value='all';sort.value='curated';sv.checked=false;apply();};
 q.addEventListener('input',()=>{state.q=q.value;apply();});sub.addEventListener('change',()=>{state.suburb=sub.value;apply();});pr.addEventListener('change',()=>{state.price=pr.value;apply();});sort.addEventListener('change',()=>{state.sort=sort.value;apply();});sv.addEventListener('change',()=>{state.saved=sv.checked;apply();});
 $('#clear-search').addEventListener('click',()=>{q.value='';state.q='';apply();q.focus();});$('#reset-filters').addEventListener('click',reset);
 content.addEventListener('click',e=>{const cat=e.target.closest('[data-category],[data-quick-category]');if(cat){state.category=cat.dataset.category||cat.dataset.quickCategory;apply();if(cat.dataset.quickCategory)$('#directory').scrollIntoView({behavior:'smooth'});}if(e.target.closest('[data-reset]'))reset();});
 apply();
}
function renderNotes(c){const root=$('#note-list');if(!root)return;const found=notes.filter(n=>n.cafe===c.id);root.innerHTML=found.length?found.map(n=>`<article class="tasting-note"><small>${esc(n.author||'Ghi chú của bạn')} · ${esc(new Date(n.created).toLocaleDateString('vi-VN'))} · Lưu riêng trên trình duyệt</small><p>${esc(n.note)}</p><button class="delete-note" type="button" data-delete-note="${esc(n.id)}">Xoá ghi chú</button></article>`).join(''):'<p class="detail-disclaimer">Chưa có ghi chú. Hãy để dành vài dòng cho lần ghé đầu tiên.</p>';}
function renderDetail(){
 const id=new URLSearchParams(location.search).get('cafe')||'hareruya-pantry',c=cafes.find(c=>c.id===id);
 if(!c){content.innerHTML='<section class="subpage empty"><h1>Chưa có quán này trong sổ.</h1><p>Liên kết có thể đã cũ. Bạn có thể chọn lại một địa điểm trong danh sách.</p><a class="primary" href="./index.html#directory">Về trang khám phá</a></section>';return;}
 document.title=c.name+' — Matcha Melbourne';
 content.innerHTML=`<section class="subpage"><div class="breadcrumb"><a href="./index.html#directory">Khám phá</a> / <a href="./index.html?suburb=${encodeURIComponent(c.suburb)}#directory">${esc(c.suburb)}</a> / ${esc(c.name)}</div><div class="detail-hero"><div><p class="eyebrow">${esc(c.suburb)} / MELBOURNE</p><h1>${esc(c.name)}</h1><p>${esc(c.description)}</p><div class="detail-actions"><button class="secondary" data-save="${c.id}" type="button" aria-pressed="${saved.includes(c.id)}">${icon('bookmark')}<span data-save-label>Lưu quán</span></button>${external(c.directions,'Chỉ đường '+icon('arrow_outward'),'primary')}<button class="secondary" type="button" data-share>Chia sẻ ${icon('ios_share')}</button></div></div><div class="detail-photo">${photo(c)}<span class="photo-caption">Ảnh minh hoạ · không phải món thực tế tại quán</span></div></div><div class="detail-layout"><div><section class="panel"><p class="eyebrow">A LITTLE TASTE OF THE MENU</p><h2>Có gì trong menu?</h2><div class="menu-tabs" role="group" aria-label="Lọc món trong menu"><button type="button" data-menu-category="all" aria-pressed="true">Tất cả món</button>${[...new Set(c.menu.map(x=>x[2]))].map(x=>`<button type="button" data-menu-category="${x}" aria-pressed="false">${esc(catName(x))}</button>`).join('')}</div><div id="menu-lines">${c.menu.map(([n,v,cat])=>`<div class="menu-line" data-menu-kind="${cat}"><span>${esc(n)}</span><span class="${v===null?'unknown-price':''}">${esc(money(v))}</span></div>`).join('')}</div><p class="detail-disclaimer">${esc(c.priceNote)}<br>Giá AUD. Đây là các món được tuyển chọn, không phải toàn bộ thực đơn.</p>${external(c.menuUrl,(c.priceType==='secondary'?'Xem nguồn menu tham khảo':'Mở menu / nguồn món')+' '+icon('arrow_outward'),'text-link')}</section><section class="panel"><p class="eyebrow">FROM YOUR MATCHA JOURNAL</p><h2>Nhớ lại tách trà này.</h2><p class="detail-disclaimer">Ghi chú chỉ lưu trên trình duyệt của bạn, không đăng công khai.</p><form id="note-form" class="note-form"><label class="field">Cảm nhận của bạn<textarea name="note" required minlength="5" maxlength="1500" placeholder="Bạn gọi món gì? Vị trà, độ ngọt hay một điều muốn nhớ…"></textarea></label><button type="submit" class="primary">Lưu ghi chú ${icon('edit_note')}</button></form><div id="note-list"></div></section></div><aside><section class="panel"><p class="eyebrow">PLAN YOUR LITTLE PAUSE</p><h2>Trước khi ghé.</h2><div class="detail-fact"><strong>Địa chỉ</strong><p>${esc(c.address)}</p></div><div class="detail-fact"><strong>Giờ mở cửa tham khảo</strong><p>${esc(c.hours)}</p></div><div class="detail-fact"><strong>Sữa & lựa chọn món</strong><p>${esc(c.milk)}</p></div><div class="detail-fact"><strong>Đồ uống tham khảo</strong><p>${esc(c.referenceLabel)}${c.reference!==null?' · '+money(c.reference):''}</p></div><div class="detail-actions">${external(c.website,'Website quán '+icon('arrow_outward'),'secondary')}</div></section><section class="panel"><p class="eyebrow">CHECK THE DETAILS</p><h2>Nguồn thông tin.</h2><ul class="source-list">${c.sources.map(([label,url])=>`<li>${external(url,esc(label)+' ↗')}</li>`).join('')}</ul><p class="detail-disclaimer">Đối chiếu nguồn ngày 26.10.2026. Kiểm tra lại thông tin trực tiếp trước khi đi; dữ liệu không cập nhật theo thời gian thực.</p></section></aside></div></section>`;
 $$('[data-menu-category]').forEach(b=>b.addEventListener('click',()=>{$$('[data-menu-category]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));$$('[data-menu-kind]').forEach(l=>l.hidden=b.dataset.menuCategory!=='all'&&b.dataset.menuCategory!==l.dataset.menuKind);}));
 $('#note-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,text=String(new FormData(form).get('note')).trim();if(text.length<5){toast('Bạn hãy viết ít nhất 5 ký tự cho ghi chú nhé.');return;}const next=[{id:uid(),cafe:c.id,note:text,created:new Date().toISOString()},...notes];if(write('matcha.notes.v1',next)){notes=next;form.reset();renderNotes(c);toast('Đã lưu ghi chú trên trình duyệt này.');}});
 content.addEventListener('click',e=>{const b=e.target.closest('[data-delete-note]');if(!b)return;const next=notes.filter(n=>n.id!==b.dataset.deleteNote);if(write('matcha.notes.v1',next)){notes=next;renderNotes(c);toast('Đã xoá ghi chú.');}});
 renderNotes(c);syncSaved();
}
async function share(){try{const url=location.href;if(navigator.share){await navigator.share({title:document.title,url});return;}await navigator.clipboard.writeText(url);toast('Đã sao chép liên kết quán.');}catch(e){if(e.name!=='AbortError'){dialog.dataset.mode='share';openDialog('<h2 id="dialog-title">Chia sẻ một góc matcha.</h2><p class="dialog-intro">Sao chép đường dẫn bên dưới để gửi cho người bạn hẹn đi cùng.</p><input class="link-input" aria-label="Liên kết quán" readonly value="'+esc(location.href)+'">');}}}
function renderMap(){
 content.innerHTML=`<section class="subpage"><div class="page-intro"><p class="eyebrow">FIND A LITTLE CORNER</p><h1>Hẹn nhau ở khu nào?</h1><p>Chọn một địa điểm để xem vị trí và đường đi. Một lần rẽ vào con hẻm mới, biết đâu lại tìm thấy quán quen.</p></div><div class="map-layout"><div class="map-sidebar"><div class="search-wrap">${icon('search')}<input type="search" id="map-search" aria-label="Tìm quán trong bản đồ" placeholder="Tên quán hoặc khu vực…"></div><label class="field" style="margin-bottom:15px">Khu vực<select id="map-suburb"><option value="all">Tất cả khu vực</option>${[...new Set(cafes.map(c=>c.suburb))].sort().map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><p class="eyebrow" id="map-count" aria-live="polite"></p><div class="map-list" id="map-list"></div></div><div class="map-main"><div class="map-frame-wrap"><iframe id="map-frame" class="map-frame" title="Vị trí quán trên Google Maps" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe><div class="map-selected" id="map-selected"></div></div><p class="map-fallback">Bản đồ từ Google Maps. Nếu bản đồ chưa tải được, dùng nút “Mở chỉ đường” bên trên.</p></div></div><section class="crawl"><p class="eyebrow">A SLOW AFTERNOON IN THE CBD</p><h2>Một vòng matcha trong thành phố.</h2><p>Gợi ý điểm dừng: Little Rogue → Hikari → Matcha Kōbō → Hareruya Pantry CBD.<br>Google Maps sẽ tính đường đi bộ; hãy kiểm tra giờ mở cửa và chọn số điểm dừng phù hợp.</p>${external('https://www.google.com/maps/dir/?api=1&origin=12%20Drewery%20Lane%20Melbourne&destination=27%20Somerset%20Place%20Melbourne&waypoints=317%20Swanston%20Street%20Melbourne%7C258%20Lonsdale%20Street%20Melbourne&travelmode=walking','Mở lộ trình đi bộ '+icon('arrow_outward'),'primary')}</section></section>`;
 let active=cafes.find(c=>c.id===new URLSearchParams(location.search).get('cafe'))?.id||cafes[0].id;
 function select(id){const c=cafes.find(c=>c.id===id);if(!c)return;active=id;$('#map-frame').src='https://maps.google.com/maps?q='+encodeURIComponent(c.name+' '+c.address)+'&z=16&output=embed';$('#map-frame').title='Google Maps · '+c.name;$('#map-selected').innerHTML=`<p class="eyebrow">${esc(c.suburb)}</p><h2>${esc(c.name)}</h2><p>${esc(c.address)}</p><div class="detail-actions">${external(c.directions,'Mở chỉ đường '+icon('arrow_outward'),'primary')}<a class="secondary" href="${cafeURL(c)}">Menu & thông tin</a></div>`;$$('[data-map-cafe]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mapCafe===active)));history.replaceState(null,'',location.pathname+'?cafe='+encodeURIComponent(id));}
 function apply(){const q=fold($('#map-search').value),s=$('#map-suburb').value,found=cafes.filter(c=>(s==='all'||c.suburb===s)&&fold(c.name+' '+c.suburb+' '+c.address).includes(q));$('#map-count').textContent=found.length+' địa điểm';$('#map-list').innerHTML=found.length?found.map(c=>`<button type="button" class="map-venue" data-map-cafe="${c.id}" aria-pressed="${c.id===active}">${photo(c)}<span><strong>${esc(c.name)}</strong><small>${esc(c.suburb)} · ${c.reference===null?'Giá chưa xác minh':money(c.reference)}</small></span></button>`).join(''):'<p class="detail-disclaimer">Chưa tìm thấy quán. Thử khu vực khác nhé.</p>';if(found.length&&!found.some(c=>c.id===active))select(found[0].id);}
 $('#map-search').addEventListener('input',apply);$('#map-suburb').addEventListener('change',apply);$('#map-list').addEventListener('click',e=>{const b=e.target.closest('[data-map-cafe]');if(b)select(b.dataset.mapCafe);});apply();select(active);
}
function renderSuggestions(){const el=$('#suggestion-list');if(!el)return;el.innerHTML=suggestions.length?suggestions.map(s=>`<article class="suggestion-item"><h3>${esc(s.name||s.cafeName||'Một góc matcha')}</h3><p>${esc(s.suburb||'')} ${s.address?'· '+esc(s.address):''}</p><p>${esc(s.note||s.description||'')}</p>${safeURL(s.url||s.website)?external(s.url||s.website,'Mở đường dẫn menu ↗'):''}<button type="button" class="reset" style="display:block" data-delete-suggestion="${esc(s.id)}">Xoá gợi ý</button></article>`).join(''):'<p class="detail-disclaimer">Chưa có gợi ý nào trong sổ tay này.</p>';$('#export-suggestions').disabled=!suggestions.length;}
function renderCommunity(){
 content.innerHTML=`<section class="subpage"><div class="page-intro"><p class="eyebrow">YOUR OWN MATCHA JOURNAL</p><h1>Giữ lại một góc bạn thích.</h1><p>Gặp một quán chưa có trong danh sách? Lưu thông tin để nhớ lần sau, hoặc xuất một bản ghi cho riêng mình.</p></div><div class="community-layout"><div><section class="panel"><h2>Thêm vào sổ tay.</h2><p class="detail-disclaimer">Biểu mẫu lưu trên trình duyệt này, không gửi gợi ý cho quán hay một ban biên tập.</p><form id="suggestion-form" class="suggestion-form"><div class="row"><label class="field">Tên quán *<input name="name" autocomplete="off" maxlength="100" required placeholder="Tên góc matcha bạn tìm thấy"></label><label class="field">Khu vực *<input name="suburb" maxlength="80" required placeholder="Ví dụ: Fitzroy"></label></div><label class="field">Địa chỉ<input name="address" maxlength="200" placeholder="Số nhà, đường, khu vực"></label><label class="field">Đường dẫn website hoặc menu<input type="url" name="url" maxlength="1000" placeholder="https://…"></label><label class="field">Món muốn thử hoặc điều muốn nhớ<textarea name="note" maxlength="1500" placeholder="Một món matcha đặc biệt, giá bạn thấy trên menu…"></textarea></label><button type="submit" class="primary">Lưu vào sổ tay ${icon('edit_note')}</button><p class="form-feedback" id="form-feedback" role="status"></p></form></section><section class="panel"><div class="section-heading"><h2>Quán muốn ghé.</h2><button type="button" id="export-suggestions" class="text-link">Xuất JSON ${icon('download')}</button></div><div id="suggestion-list"></div></section></div><aside><section class="panel faq"><p class="eyebrow">A FEW LITTLE DETAILS</p><h2>Bạn có thể muốn biết.</h2><details open><summary>Giá trong danh sách có phải giá hiện tại?</summary><p>Đó là giá từ nguồn online đã đối chiếu ngày 26.10.2026. Trang ghi rõ nguồn chính thức, nguồn tổng hợp, menu theo mùa hoặc chưa có giá xác minh. Giá tại quán có thể thay đổi.</p></details><details><summary>Vì sao một số quán chưa có giá?</summary><p>Một số website chỉ có tên món hoặc niêm yết giá tại cửa hàng. Trang giữ nguyên trạng thái chưa xác minh, kèm nguồn để bạn tiện xem.</p></details><details><summary>Ảnh có chụp tại các quán không?</summary><p>Ảnh là hình minh hoạ được tạo cho website, không phải ảnh địa điểm hoặc món thực tế của các quán.</p></details><details><summary>Sổ tay và quán đã lưu nằm ở đâu?</summary><p>Dữ liệu nằm trong trình duyệt bạn đang dùng. Chưa có đăng nhập hay đồng bộ. Xoá dữ liệu trình duyệt có thể làm mất ghi chú; bạn có thể xuất gợi ý quán thành JSON để giữ một bản.</p></details><details><summary>Menu hiển thị có đầy đủ không?</summary><p>Mỗi quán có một số món tuyển chọn. Dùng liên kết menu gốc trong hồ sơ quán để xem thêm món, thành phần và phụ thu.</p></details></section><section class="panel" style="background:#e7ecd9"><h2>Đi cùng một người bạn.</h2><p class="detail-disclaimer">Mở hồ sơ quán và chọn “Chia sẻ” để gửi đường dẫn, hoặc tìm một khu vực thuận tiện cho cả hai.</p><a class="text-link" href="./matcha-map-and-suburbs.html">Chọn điểm hẹn ${icon('arrow_outward')}</a></section></aside></div></section>`;
 $('#suggestion-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,d=Object.fromEntries(new FormData(form));for(const k in d)d[k]=String(d[k]).trim();if(!d.name||!d.suburb){$('#form-feedback').textContent='Bạn hãy thêm tên quán và khu vực nhé.';return;}if(d.url&&!safeURL(d.url)){$('#form-feedback').textContent='Dùng đường dẫn bắt đầu bằng https:// hoặc http:// nhé.';return;}const next=[{...d,id:uid(),created:new Date().toISOString()},...suggestions];if(write('matcha.suggestions.v1',next)){suggestions=next;form.reset();$('#form-feedback').textContent='Đã lưu vào sổ tay trên trình duyệt này.';renderSuggestions();}});
 $('#suggestion-list').addEventListener('click',e=>{const b=e.target.closest('[data-delete-suggestion]');if(!b)return;const next=suggestions.filter(s=>s.id!==b.dataset.deleteSuggestion);if(write('matcha.suggestions.v1',next)){suggestions=next;renderSuggestions();toast('Đã xoá gợi ý khỏi sổ tay.');}});
 $('#export-suggestions').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(suggestions,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='matcha-melbourne-so-tay.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã tạo bản xuất sổ tay.');});
 renderSuggestions();
}
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){toggleSave(save.dataset.save);return;}if(e.target.closest('[data-open-saved]'))openSaved();if(e.target.closest('[data-about]'))about();if(e.target.closest('[data-share]'))share();});
$('.mobile-menu-button').addEventListener('click',e=>{const b=e.currentTarget,n=$('#mobile-nav');n.hidden=!n.hidden;b.setAttribute('aria-expanded',String(!n.hidden));b.setAttribute('aria-label',n.hidden?'Mở điều hướng':'Đóng điều hướng');});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){const input=$('#cafe-search')||$('#map-search');if(input&&!dialog.open){e.preventDefault();input.focus();input.scrollIntoView({block:'center',behavior:'smooth'});}}if(e.key==='Escape'){$('#mobile-nav').hidden=true;$('.mobile-menu-button').setAttribute('aria-expanded','false');}});
$$('span.icon').forEach(el=>el.outerHTML=icon(el.textContent.trim()));
({directory:renderDirectory,detail:renderDetail,map:renderMap,community:renderCommunity}[document.body.dataset.page]||renderDirectory)();syncSaved();
})();
